#!/usr/bin/env node
// Standalone CLI / dev smoke helper. AI no longer invokes this — the dispatcher
// calls mcp__orchestra-utils__claude_md instead, which inlines the same logic
// from this file. Retained for local debugging and the test suite.
//
// Write the orchestra rules body to <root>/.orchestra/claude-md/orchestra.md and
// ensure <root>/CLAUDE.md imports it via a single `@`-import line. The import line
// is a fixed string, so it is its own idempotency anchor — no marker block needed.
// Idempotent:
//   CLAUDE.md missing              → write `# CLAUDE.md` + @-import line
//   CLAUDE.md exists, no import    → append @-import line (preserves user content)
//   CLAUDE.md exists, import there → leave CLAUDE.md alone
//   rules file drifted             → rewrite it (action: updated)
//   already up-to-date             → no write

import { existsSync, readFileSync, mkdirSync } from "node:fs";
import { dirname, resolve, join } from "node:path";
import { fileURLToPath } from "node:url";
import { safeRead, safeWrite } from "./safe-fs.js";

const __dirname = dirname(fileURLToPath(import.meta.url));

const IMPORT_REL = ".orchestra/claude-md/orchestra.md";
const IMPORT_LINE = `@${IMPORT_REL}`;
const RULES_BANNER = "<!-- generated by orchestra:claude_md — edits overwritten -->\n\n";
const TEMPLATE = resolve(__dirname, "..", "references", "consumer-claude-md.template.md");

function rulesBody() {
  return `${RULES_BANNER}${readFileSync(TEMPLATE, "utf8").trim()}\n`;
}

function main() {
  const root = process.argv[2] || process.cwd();
  const target = join(root, "CLAUDE.md");
  const rulesTarget = join(root, ".orchestra", "claude-md", "orchestra.md");
  const body = rulesBody();

  // 1. Rules file always reflects the current template (rewrite on drift).
  let rulesChanged = true;
  if (existsSync(rulesTarget)) {
    const rbuf = safeRead(rulesTarget);
    if (rbuf === null) {
      process.stderr.write(`bootstrap-consumer-claude-md: refusing to operate on ${rulesTarget} (symlink or non-file)\n`);
      return 1;
    }
    rulesChanged = rbuf.toString("utf8") !== body;
  }
  if (rulesChanged) {
    mkdirSync(dirname(rulesTarget), { recursive: true });
    safeWrite(rulesTarget, body);
  }

  // 2. Ensure CLAUDE.md imports the rules file.
  if (!existsSync(target)) {
    safeWrite(target, `# CLAUDE.md\n\n${IMPORT_LINE}\n`);
    process.stdout.write(`bootstrap-consumer-claude-md: created ${target} (+ ${rulesTarget})\n`);
    return 0;
  }

  const buf = safeRead(target);
  if (buf === null) {
    process.stderr.write(`bootstrap-consumer-claude-md: refusing to operate on ${target} (symlink or non-file)\n`);
    return 1;
  }
  const existing = buf.toString("utf8");
  if (existing.includes(IMPORT_LINE)) {
    const action = rulesChanged ? "updated rules in" : "unchanged";
    process.stdout.write(`bootstrap-consumer-claude-md: ${action} ${rulesTarget}\n`);
    return 0;
  }
  const sep = existing.endsWith("\n") ? "\n" : "\n\n";
  safeWrite(target, `${existing}${sep}${IMPORT_LINE}\n`);
  process.stdout.write(`bootstrap-consumer-claude-md: appended import to ${target} (+ ${rulesTarget})\n`);
  return 0;
}

process.exit(main());
